const state = $getWorkflowStaticData('global');
const pendingEdits = state.telegram_pending_edits || {};
const callback = $json.callback_query || {};
const message = $json.message || callback.message || {};
const text = String(message.text || '').trim();
const callbackData = String(callback.data || '').trim();
const chatId = message.chat?.id;
const actorUserId = callback.from?.id || message.from?.id || null;
const notifyChatId = actorUserId || chatId;
const moderationCommand = text.match(/^\/(approve|reject)\s+(\d+)(?:\s+(.+))?\s*$/i);
const callbackCommand = callbackData.match(/^(approve|reject|edit|regenerate):(\d+)$/i);
const chatIdCommand = text.match(/^\/(?:chatid|id)(?:@\w+)?\s*$/i);
const command = moderationCommand || callbackCommand;
const allowed = String($env.TELEGRAM_MODERATOR_IDS || '').split(',').map((value) => value.trim()).filter(Boolean);
const pending = actorUserId ? pendingEdits[String(actorUserId)] : null;
let action = command ? command[1].toLowerCase() : chatIdCommand ? 'chatid' : 'help';
let candidateId = command ? Number(command[2]) : null;
let editInstruction = '';
if (!command && !chatIdCommand && pending && pending.expires_at > Date.now() && text) {
  if (/^\/cancel(?:@\w+)?\s*$/i.test(text)) {
    action = 'edit_cancel';
    candidateId = Number(pending.candidate_id);
    delete pendingEdits[String(actorUserId)];
  } else {
    action = 'edit_submit';
    candidateId = Number(pending.candidate_id);
    editInstruction = text;
    delete pendingEdits[String(actorUserId)];
  }
}
if (action === 'edit' && allowed.includes(String(actorUserId))) {
  pendingEdits[String(actorUserId)] = { candidate_id: candidateId, chat_id: chatId, moderation_message_id: message.message_id || null, expires_at: Date.now() + 15 * 60 * 1000 };
}
state.telegram_pending_edits = pendingEdits;
const requiresAuth = ['approve', 'reject', 'edit', 'regenerate', 'edit_submit', 'edit_cancel'].includes(action);
const authorized = !requiresAuth || allowed.includes(String(actorUserId));
return { json: { action, candidate_id: candidateId, reject_reason: moderationCommand?.[3] || 'інше', reply_chat_id: chatId, notify_chat_id: notifyChatId, actor_user_id: actorUserId, authorized, chat_type: message.chat?.type || '', chat_title: message.chat?.title || '', moderation_chat_id: pending?.chat_id || chatId, moderation_message_id: pending?.moderation_message_id || message.message_id || null, input_message_id: message.message_id || null, review_text: String(message.text || ''), edit_instruction: editInstruction, edit_valid: editInstruction.length > 0, event_type: $json.event_type || 'message', callback_query_id: callback.id || null } };

